insert into public.product_updates(kind,version,status,content,sort_order,visible) values ('release','1.0.5','published','{"es":{"title":"Una experiencia Pro más clara","body":"Versión 1.0.5: mejoras en la presentación de planes Pro, informes de estadísticas en PDF, plantillas de sesión, notas de voz privadas y estabilidad."},"en":{"title":"A clearer Pro experience","body":"Version 1.0.5: clearer Pro plans, improved PDF statistics reports, session templates, private voice notes and stability improvements."},"pt":{"title":"Uma experiência Pro mais clara","body":"Versão 1.0.5: planos Pro mais claros, relatórios de estatísticas em PDF melhorados, modelos de sessão, notas de voz privadas e melhorias de estabilidade."},"fr":{"title":"Une expérience Pro plus claire","body":"Version 1.0.5 : plans Pro plus clairs, rapports statistiques PDF améliorés, modèles de session, notes vocales privées et stabilité."},"de":{"title":"Ein übersichtlicheres Pro-Erlebnis","body":"Version 1.0.5: klarere Pro-Angebote, verbesserte PDF-Statistiken, Session-Vorlagen, private Sprachnotizen und mehr Stabilität."},"it":{"title":"Un’esperienza Pro più chiara","body":"Versione 1.0.5: piani Pro più chiari, report statistici PDF migliorati, modelli di sessione, note vocali private e maggiore stabilità."},"ja":{"title":"より分かりやすいPro体験","body":"バージョン1.0.5：Proプランの表示改善、PDF統計レポート、セッションテンプレート、非公開の音声メモ、安定性の改善。"}}'::jsonb,0,true),('roadmap',null,'in_development','{"es":{"title":"Tu opinión y tus monedas, dentro de la app","body":"Preparamos un formulario de ideas y problemas, la elección de moneda por sesión y un espacio para consultar novedades y próximos pasos."},"en":{"title":"Your feedback and currencies in the app","body":"We are preparing an ideas and issues form, currency selection per session, and a space for updates and next steps."},"pt":{"title":"As suas sugestões e moedas na app","body":"Estamos a preparar um formulário de sugestões e problemas, a escolha de moeda por sessão e um espaço de novidades e próximos passos."},"fr":{"title":"Vos retours et devises dans l’app","body":"Nous préparons un formulaire de suggestions et de problèmes, le choix de devise par session et un espace de nouveautés et prochaines étapes."},"de":{"title":"Feedback und Währungen direkt in der App","body":"Wir bereiten ein Formular für Ideen und Probleme, eine Währungsauswahl pro Session sowie Neuigkeiten und nächste Schritte vor."},"it":{"title":"Feedback e valute nell’app","body":"Prepariamo un modulo per idee e problemi, la scelta della valuta per sessione e uno spazio per novità e prossimi passi."},"ja":{"title":"アプリ内のフィードバックと通貨設定","body":"アイデアや不具合の送信フォーム、セッションごとの通貨選択、新機能と今後の予定を確認できる画面を準備しています。"}}'::jsonb,0,true);
